 #[ignore="LITO_SHARED_RESOURCE_ROOT; original228/132 after target departure, memory fragments only"]
 fn original_protection_visual_is_world_audio_and_not_a_status_timer(){let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit shared root").into();let cancel=AtomicBool::new(false);let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}let own=w.own_actor().unwrap().clone();let mut other=own.clone();other.id=0x71234567;other.incarnation+=1;other.x+=1;w.actors.insert(other.id,other.clone());let mut b=vec![0x37];b.extend(other.id.to_le_bytes());b.extend(228_u16.to_le_bytes());w.accept(&b).unwrap();w.actors.remove(&other.id);let authority=(w.hp,w.mp,w.movement_blocks.clone());let mut e=Effects::default();e.prepare(&root,&w,&cancel);assert!(e.additional_error.is_none());let view=ViewProjection{anchor_cell:WorldCell{x:i32::from(own.x),y:i32::from(own.y)},anchor_pixel:super::super::world_map::PixelPoint{x:400,y:300}};let mut q=vec![];let(_,audio)=e.draw_to(&w,&mut super::super::native_world_effects::Target::Fragments(&mut q),view,0);assert_eq!(q.len(),1);assert_eq!(audio.iter().filter(|e|e.actor==0&&e.sound==Some(132)&&e.prepared_audio.is_some()).count(),1);drop(q);assert_eq!((w.hp,w.mp,w.movement_blocks.clone()),authority);let bank=e.additional_bank.as_ref().unwrap();let mut p=Clip::new(Arc::clone(bank.animation(228,0).unwrap())).unwrap().start();let mut s=p.advance(0).unwrap();let mut at=0;while !s.finished{at=p.next_callback_millis().unwrap();s=p.advance(at*1_000_000).unwrap();}assert_eq!(at,830);}
